'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>{v=Number(v||0);return '₫'+(Math.abs(v)>=1e9?(v/1e9).toFixed(2)+'B':Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'M':v.toLocaleString('en-US',{maximumFractionDigits:0}));};
const fullMoney=v=>'VND '+Number(v||0).toLocaleString('en-US',{maximumFractionDigits:0});
const when=v=>new Date(Number(v)*1000).toLocaleString('en-GB');
const sentence=v=>String(v??'').replaceAll('_',' ').replace(/^\p{L}/u,c=>c.toUpperCase());
const place=v=>String(v??'').normalize('NFC').replace(/(^|[\s-])\p{L}/gu,c=>c.toLocaleUpperCase('vi-VN'));
const factorLabel=v=>({'log area':'Land area (log scale)','log road':'Road width (log scale)','floors':'Number of floors','Province':'Province','District':'District'}[v]||sentence(v));
const greeting=()=>new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
function polishOptions(){for(const option of $$('#districtSelect option,#wardSelect option,#streetSelect option'))if(option.value)option.textContent=place(option.value)+(option.textContent.includes('(saved;')?' (saved; not in area catalog)':'');}
function polishCopy(){
 const title=$('.page-head h1');if(S.view==='overview'&&title)title.textContent=`${greeting()}, ${S.summary.profile.name.split(' ')[1]||S.summary.profile.name}.`;
 for(const node of $$('.factor>span'))node.textContent=factorLabel(node.textContent);
 for(const node of $$('.component-label>span:first-child,.check,.metric-pair>span'))if(!node.children.length)node.textContent=sentence(node.textContent);
 for(const node of $$('.property-value')){const address=node.previousElementSibling;if(address?.classList.contains('tiny')){const [location,area]=address.textContent.split(' · ');address.textContent=place(location)+(area?' · '+area:'');}}
 for(const node of $$('.street-row b,#streetDetail h3'))node.textContent=place(node.textContent);
 for(const node of $$('.street-row span')){const [district,...rest]=node.textContent.split(' · ');node.textContent=[place(district),...rest].join(' · ');}
 const walker=document.createTreeWalker($('#content'),NodeFilter.SHOW_TEXT);let text;
 while((text=walker.nextNode())){if(text.parentElement.closest('.evidence,code,option,input,textarea'))continue;text.textContent=text.textContent.replace(/\bPhase1\b/g,'Phase 1').replace(/\bPhase3\b/g,'Phase 3');}
 if(S.view==='health'&&$('.page-head p'))$('.page-head p').textContent='Edit your self-reported demo inputs. Changing monthly income requires a new evidence review.';
 for(const node of $$('.evidence'))node.setAttribute('tabindex','0');
}
let navigationVersion=0;
const S={user:null,view:'overview',summary:null,customers:[],cid:'minh',market:null,map:null,markers:[],status:null};
const NAV={customer:[['overview','◈','Overview'],['property','⌂','Property value'],['health','◎','Financial health'],['documents','▤','Documents'],['map','⌁','Area intelligence']],
 advisor:[['clients','◈','Client workspace'],['appointments','▦','Conversations'],['property','⌂','Property valuation'],['documents','▤','Customer evidence']],
 authenticator:[['reviews','✓','Review queue'],['signals','⌁','Market signals'],['sources','▧','Evidence sources'],['audit','≡','Audit log']]};
async function api(path,data){
 const post=data!==undefined,headers=post?{'Content-Type':'application/json'}:{};
 if(post&&typeof crypto!=='undefined'&&crypto.randomUUID)headers['Idempotency-Key']=crypto.randomUUID();
 const body=post?JSON.stringify(data):undefined;
 const controller=typeof AbortController==='function'?new AbortController():null;
 const timer=controller?setTimeout(()=>controller.abort(),90000):null;
 try{
  const r=await fetch(path,{method:post?'POST':'GET',credentials:'same-origin',headers,body,...(controller?{signal:controller.signal}:{})});
  const d=await r.json();if(!r.ok){if(r.status===401&&S.user)await signedOut();throw Error((d.error||'Request failed')+(d.request_id?' · Reference '+d.request_id:''));}return d;
 }catch(error){if(error.name==='AbortError')throw Error('Request timed out. Check the saved record before repeating this operation.');throw error;}
 finally{if(timer)clearTimeout(timer);}
}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function button(label,action,cls='',extra=''){return `<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function badge(status){return `<span class="pill ${status==='pending'?'warning':status==='rejected'?'danger':''}">${esc(sentence(status))}</span>`;}
function head(title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">${esc(sentence(S.user.role))} workspace</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function stat(label,value,note,icon='↗'){return `<article class="card hover"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-number">${value}</div><div class="stat-footer">${note}</div></article>`;}
function appointmentButton(){return button('Plan a conversation ↗','appointment','primary');}
function reportButton(){return `<a class="button" href="/api/report?customer=${encodeURIComponent(S.cid)}">Export report ↓</a>`;}
async function signedOut(){navigationVersion++;workspace.reset();S.user=null;S.summary=null;if(S.map){S.map.remove();S.map=null;}$('#content').replaceChildren();$('#shell').hidden=true;$('#login').hidden=false;$('#password').value='';for(const d of $$('dialog[open]'))d.close();}
async function signIn(user){S.user=user;S.cid=user.customer_id||'minh';$('#login').hidden=true;$('#shell').hidden=false;$('#roleName').textContent=sentence(user.role);$('#userName').textContent=sentence(user.email.split('@')[0]);$('#avatar').textContent=user.role.slice(0,2).toUpperCase();$('#workspaceTag').textContent=sentence(user.role)+' workspace';$('.assistant-launcher').hidden=user.role==='authenticator';S.market=await api('/api/market');await navigate(NAV[user.role][0][0]);api('/api/status').then(x=>{if(S.user===user)S.status=x;}).catch(()=>{});}
async function navigate(view,cid=S.cid){if(!S.user||!NAV[S.user.role].some(x=>x[0]===view))return;workspace.remember();const version=++navigationVersion;S.cid=cid;S.view=view;if(S.map){S.map.remove();S.map=null;}$('#nav').innerHTML=NAV[S.user.role].map(([key,icon,label])=>`<button data-nav="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}><span>${icon}</span>${label}</button>`).join('');$('#pageLabel').textContent=NAV[S.user.role].find(x=>x[0]===view)[2];$('.sidebar').classList.remove('open');$('#content').innerHTML='<div class="loading"><div class="spinner"></div>Loading authorized records…</div>';
 try{if(S.user.role!=='authenticator'){if(S.user.role==='advisor'){const customers=await api('/api/customers');if(version!==navigationVersion)return;S.customers=customers;if(!S.customers.some(x=>x.profile.id===S.cid))S.cid=S.customers[0].profile.id;}const summary=await api('/api/summary?customer='+S.cid);if(version!==navigationVersion)return;S.summary=summary;}await render(version);if(version===navigationVersion&&S.user)workspace.restore();}catch(e){if(version===navigationVersion)$('#content').innerHTML=`<div class="notice warning">${esc(e.message)}</div>`;}}
function healthHero(s){const h=s.health;return `<section class="health-hero"><div><span class="eyebrow">YOUR FINANCIAL HEALTH</span><h2>A stronger foundation starts here.</h2><div class="score-row"><strong class="score-number">${h.score}</strong><span>/ 1,000</span></div><div class="row"><span class="pill">${h.status}</span><span class="tiny" style="color:#bfd2c4">${h.rules_version}</span></div><p class="score-note" style="margin-top:18px">Ahead of <strong>${h.percentile}%</strong> of a ${h.peer_count}-person <strong>synthetic</strong> comparison group.</p></div><div class="health-right">${Object.entries(h.components).map(([k,v])=>`<div class="component"><div class="component-label"><span>${esc(k)}</span><span>${Math.round(v)}/100</span></div><div class="track"><i style="width:${Math.round(v)}%"></i></div></div>`).join('')}<p>Rule-based demo, not a bank credit score. Your inputs remain under your control.</p></div></section>`;}
function propertyCard(s){
 const p=s.property;
 if(!p)return `<article class="card"><h3>No property estimate yet</h3><p class="muted">Add your first property to complete the picture.</p>${button('Add a property','property','primary')}</article>`;
 const r=p.result,preview=p.status==='live preview';
 const explain=preview?'<span class="tiny">Save this estimate before discussing it with Finx.</span>':button('Explain this estimate','chat');
 return `<article class="card hover"><div class="card-head"><h3>Your property, in perspective</h3>${badge(p.status)}</div><span class="tiny">${esc(p.input.ward||'Ward not specified')}, ${esc(p.input.district)} · ${p.input.area} m²</span><div class="property-value">${money(r.value)}</div><p class="property-band">Indicative 90% band ${money(r.low)} – ${money(r.high)}</p><div class="row">${button('Refine valuation ↗','property')}${explain}</div><p class="source-label">Actual local LightGBM inference · ${esc(r.method)} · ${esc(r.model_version)}<br>Asking-price research model, not an appraisal. ${r.completeness}% profile completeness.</p></article>`;
}
function opportunities(s){const h=s.health;return `<article class="card"><div class="card-head"><h3>Your next best conversations</h3><span class="tiny">ILLUSTRATIVE</span></div><div class="opportunity"><span class="opportunity-icon">⌂</span><div><b>Explore a prudent borrowing budget</b><p>Illustrative additional capacity ${money(h.illustrative_borrowing_capacity)}. Uses assumed rates and affordability rules, not bank eligibility.</p><button class="text-button" data-action="simulate">Open simulator →</button></div></div><div class="opportunity"><span class="opportunity-icon">▤</span><div><b>${s.profile.verified?'Keep your evidence current':'Make your income evidence-led'}</b><p>${s.profile.verified?'An approved synthetic payslip supports your stated monthly income.':'Upload a payslip, inspect the extracted fields and request a human review.'}</p><button class="text-button" data-action="documents">${s.profile.verified?'View evidence':'Upload sample payslip'} →</button></div></div><div class="opportunity"><span class="opportunity-icon">◎</span><div><b>${h.buffer_months<6?'Strengthen your emergency buffer':'Give your savings a clear purpose'}</b><p>Your current cash covers ${h.buffer_months.toFixed(1)} months of stated expenses and debt payments.</p><button class="text-button" data-action="appointment">Discuss your goals →</button></div></div></article>`;}
function overview(){const s=S.summary,p=s.profile,h=s.health;return head(`Good morning, ${esc(p.name.split(' ')[1]||p.name)}.`,`Your home and financial wellbeing, connected in one place.`,reportButton())+healthHero(s)+`<div class="grid four section">${stat('Monthly income',money(p.income),p.verified?'Approved synthetic payslip':'Self-reported · unverified','↗')}${stat('Monthly surplus',money(h.monthly_surplus),'Income − expenses − debt payments','＋')}${stat('Cash reserve',money(p.cash),h.buffer_months.toFixed(1)+' months of essential outflow','◎')}${stat('Debt-service ratio',(100*h.dsr).toFixed(1)+'%','Monthly debt payment / income','◴')}</div><div class="grid section">${propertyCard(s)}${opportunities(s)}</div><div class="grid section"><article class="card"><div class="card-head"><h3>Cash-flow illustration</h3><span class="tiny">SYNTHETIC PATTERN</span></div><p class="tiny">An illustrative six-month pattern scaled to your current profile, not imported bank transactions.</p><div class="chart">${['May','Jun','Jul','Aug','Sep','Oct'].map((m,i)=>`<div><i style="height:${65+i*4}%"></i><i class="expense" style="height:${Math.max(15,Math.min(95,(p.expenses+p.debt_payment)/Math.max(p.income,1)*80))}%"></i><span>${m}</span></div>`).join('')}</div><p class="tiny" style="margin-top:35px">● Income illustration &nbsp; <span style="color:#98b67f">●</span> Expenses + debt</p></article><article class="card"><span class="eyebrow">FINX, YOUR EVIDENCE ASSISTANT</span><h2>Understand the “why”<br>behind your picture.</h2><p class="muted" style="margin:13px 0 22px">Ask about your score, your estimate or your next prudent step. Only this customer's authorized evidence is supplied.</p>${button('Start a conversation ↗','chat','dark')}<p class="source-label">Qwen via private SSH when available. Clearly labelled evidence-only mode otherwise.</p></article></div>`;}
function customerPicker(){return S.user.role==='advisor'?`<label>Assigned customer<select id="customerPicker">${S.customers.map(s=>`<option value="${esc(s.profile.id)}" ${s.profile.id===S.cid?'selected':''}>${esc(s.profile.name)}</option>`).join('')}</select></label>`:'';}
function propertyPage(){const raw=S.summary.property?.input||{};return head('A more informed property estimate.','Detailed inputs are sent to the local AVM, not a fixed demo-price function.',reportButton())+customerPicker()+`<div class="grid"><article class="card"><div class="card-head"><h3>Property profile</h3><span class="pill">HANOI · LANDED HOUSES</span></div><form id="valuationForm"><div class="form-grid"><label>District<select name="district" id="districtSelect"></select></label><label>Ward<select name="ward" id="wardSelect"></select></label><label class="span2">Street<select name="street" id="streetSelect"></select></label><label>Land area (m²)<input name="area" type="number" min="10" max="2000" step=".1" value="${raw.area||52.3}" required></label><label>Floors<input name="floors" type="number" min="1" max="30" value="${raw.floors||4}"></label><label>Frontage (m)<input name="frontage" type="number" min="0" max="100" step=".1" value="${raw.frontage||4}"></label><label>Road / alley width (m)<input name="road" type="number" min="0" max="100" step=".1" value="${raw.road||4}"></label><label>Bedrooms<input name="bedrooms" type="number" min="0" max="100" value="${raw.bedrooms||3}"></label><label>Bathrooms<input name="bathrooms" type="number" min="0" max="100" value="${raw.bathrooms||3}"></label><label>Property subtype<select name="subtype"><option value="normal_house">Landed house</option><option value="alley_frontage_house">Alley-front house</option><option value="frontage_house">Street-front house</option><option value="villa">Villa</option></select></label><label>Model option<select name="method"><option value="lightgbm">LightGBM baseline</option><option value="hierarchical">GBM + hierarchy calibration (research)</option></select></label></div><div class="notice">Hanoi demo scope. Estimates model historical asking prices. The research calibration option is not a production model upgrade.</div><div class="form-footer"><span class="tiny">Every calculation is recorded with a model hash.</span><button class="button primary" type="submit">Calculate estimate ↗</button></div></form></article><div><div id="valuationResult">${propertyCard(S.summary)}</div><article class="card section"><h3>What shapes the model estimate</h3><p class="tiny" style="margin:10px 0">Native SHAP contributions in log-price space. These are model associations, not causal price premiums.</p><div id="factors">${factorList(S.summary.property?.result)}</div></article></div></div>`;}
function factorList(r){return r?.factors?.map(f=>`<div class="factor"><span>${esc(f.factor)}</span><b class="${f.log_contribution>=0?'positive':'negative'}">${f.log_contribution>=0?'+':''}${f.log_contribution.toFixed(3)}</b></div>`).join('')||'<p class="tiny">Calculate an estimate to see actual model contributions.</p>';}
function populateDistricts(){const raw=S.summary.property?.input||{};$('#districtSelect').innerHTML=S.market.districts.map(d=>`<option value="${esc(d.label)}">${esc(d.label)}</option>`).join('');if(S.market.districts.some(d=>d.label===raw.district))$('#districtSelect').value=raw.district;populateWards(raw.ward,raw.street);const f=$('#valuationForm');if(raw.method)f.elements.method.value=raw.method;if(raw.subtype)f.elements.subtype.value=raw.subtype;}
function populateWards(ward,street){const d=S.market.districts.find(d=>d.label===$('#districtSelect').value);$('#wardSelect').innerHTML='<option value="">Not specified</option>'+d.wards.map(w=>`<option value="${esc(w.label)}">${esc(w.label)}</option>`).join('');if(d.wards.some(w=>w.label===ward))$('#wardSelect').value=ward;populateStreets(street);}
function populateStreets(street){const d=S.market.districts.find(d=>d.label===$('#districtSelect').value);const w=d.wards.find(w=>w.label===$('#wardSelect').value);const streets=w?.streets||[];$('#streetSelect').innerHTML='<option value="">Not specified</option>'+streets.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(street&&!streets.includes(street))$('#streetSelect').add(new Option(street+' (saved; not in area catalog)',street));if(street)$('#streetSelect').value=street;}
function healthPage(){const s=S.summary,p=s.profile;return head('Your financial health, explained.','Edit self-reported demo inputs. Changing them resets income verification.',reportButton())+healthHero(s)+`<div class="grid section"><article class="card"><h3>Financial profile</h3><form id="profileForm" style="margin-top:20px"><div class="form-grid">${[['income','Monthly income'],['expenses','Monthly living expenses'],['debt_payment','Monthly debt payments'],['cash','Liquid savings'],['debt','Outstanding loan principal']].map(([k,l])=>`<label>${l} (VND)<input type="number" name="${k}" min="0" max="1000000000000" value="${p[k]}" required></label>`).join('')}</div><button class="button primary" type="submit">Save self-reported profile</button></form></article><article class="card"><h3>How this demo score works</h3><div class="metric-pair"><span>Cash-flow resilience</span><strong>35%</strong></div><div class="metric-pair"><span>Debt-service resilience</span><strong>30%</strong></div><div class="metric-pair"><span>Emergency buffer</span><strong>25%</strong></div><div class="metric-pair"><span>Evidence completeness</span><strong>10%</strong></div><p class="notice">${esc(s.health.disclaimer)}</p>${button('View borrowing simulator','simulate')}${button('Review my documents','documents')}</article></div>`;}
async function documentsPage(){const docs=await api('/api/documents?customer='+S.cid);return head('Evidence that completes your picture.','Read, validate, review. No extracted salary becomes trusted automatically.')+`<div class="grid"><article class="card"><h3>Try the synthetic sample</h3><p class="muted" style="margin:10px 0 17px">A fictional payslip for Nguyen Minh Long, with checkable totals. No real employer or bank account.</p><div class="row"><a class="button" href="/api/sample/payslip.pdf">Download PDF ↓</a><a class="button" href="/api/sample/payslip.png">Download scan PNG ↓</a></div><div class="upload-box section"><h3>Upload a demo payslip</h3><p class="tiny">PDF, PNG or JPEG · up to 6 MB · up to 5 pages<br>Do not upload real bank records or identity documents.</p><form id="uploadForm"><input id="documentFile" type="file" accept="application/pdf,image/png,image/jpeg" required><button class="button primary" type="submit">Extract & request review ↗</button></form></div><p class="source-label">PDF text is extracted locally. Scanned images use local Apple Vision OCR when available. Neither is treated as verification.</p></article><article class="card"><h3>Your document trail</h3>${docs.length?docs.map(d=>`<div class="document-card"><div class="card-head"><b>${esc(d.name)}</b>${badge(d.status)}</div><p class="tiny">${esc(d.extraction.engine)} · ${when(d.created)}<br>SHA256 ${esc(d.sha256.slice(0,20))}…</p>${extractionView(d.extraction)}${d.note?`<p class="notice">Reviewer note: ${esc(d.note)}</p>`:''}<a class="text-button" href="/api/documents/${d.id}/file">Download original →</a></div>`).join(''):'<div class="empty">No documents uploaded yet. Start with the sample.</div>'}</article></div>`;}
function extractionView(ex){return `<div class="check-grid">${Object.entries(ex.checks||{}).map(([k,v])=>`<div class="check ${v?'':'fail'}">${v?'✓':'!'} ${esc(sentence(k))}</div>`).join('')}</div>${Object.keys(ex.fields||{}).length?`<div class="evidence">${Object.entries(ex.fields).map(([k,v])=>`${esc(sentence(k))}: ${fullMoney(v)}`).join('\n')}</div>`:''}${(ex.warnings||[]).map(w=>`<p class="error">${esc(w)}</p>`).join('')}<details style="margin:12px 0"><summary class="tiny">Field provenance and page coordinates</summary>${Object.entries(ex.evidence||{}).map(([k,v])=>`<p class="tiny"><b>${esc(sentence(k))}</b>: ${esc(v.text)}<br>${(v.spans||[]).map(s=>`Page ${s.page} · ${esc(s.box.map(n=>Number(n).toFixed(2)).join(', '))}`).join('<br>')||'No exact box matched; inspect the original.'}</p>`).join('')}</details>`;}
function clientPage(){return head('The right conversation starts with context.','Assigned synthetic customers only. Select a profile to inspect its actual stored state.',appointmentButton())+`<div class="grid" style="grid-template-columns:1.5fr 1fr"><article class="card"><div class="card-head"><h3>Priority clients</h3><span class="pill">${S.customers.length} ASSIGNED</span></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Health</th><th>Property</th><th>Evidence</th></tr></thead><tbody>${S.customers.map(s=>`<tr data-customer="${s.profile.id}" class="${s.profile.id===S.cid?'selected-row':''}"><td><b>${esc(s.profile.name)}</b><br><small>${esc(s.profile.goal)}</small></td><td>${s.health.score}<br><small>${s.health.status}</small></td><td>${money(s.property?.result.value)}</td><td>${badge(s.profile.verified?'verified demo':'pending')}</td></tr>`).join('')}</tbody></table></div></article><article class="card"><span class="eyebrow">SELECTED CUSTOMER</span><h2>${esc(S.summary.profile.name)}</h2><div class="metric-pair"><span>Financial health</span><strong>${S.summary.health.score}/1000</strong></div><div class="metric-pair"><span>Debt-service ratio</span><strong>${(100*S.summary.health.dsr).toFixed(1)}%</strong></div><div class="metric-pair"><span>Monthly surplus</span><strong>${money(S.summary.health.monthly_surplus)}</strong></div><p class="notice">${S.summary.profile.verified?'Income is supported by a reviewed synthetic payslip.':'Income is unverified. Confirm evidence before discussing a product.'}</p><div class="row">${button('Value property','property')}${button('Explain profile','chat')}${reportButton()}</div></article></div><div class="section">${opportunities(S.summary)}</div>`;}
function appointmentsPage(){return head('Conversations with a purpose.','Requests are saved locally. They are not real bank bookings.',appointmentButton())+customerPicker()+`<article class="card"><h3>${esc(S.summary.profile.name)} · Conversation requests</h3>${S.summary.appointments.length?`<table><thead><tr><th>When</th><th>Topic</th><th>Status</th></tr></thead><tbody>${S.summary.appointments.map(a=>`<tr><td>${esc(a.at.replace('T',' '))}</td><td>${esc(a.note)}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No requests yet. Plan a conversation to get started.</div>'}</article>`;}
async function reviewPage(){const r=await api('/api/reviews');const pending=r.documents.filter(x=>x.status==='pending').length+r.properties.filter(x=>x.status==='pending').length;return head('Human judgement, in the loop.','Review extracted evidence and model outputs. Every action is recorded.',`<span class="pill warning">${pending} PENDING</span>`)+`<div class="grid"><article class="card"><h3>Income evidence</h3>${r.documents.length?r.documents.map(d=>`<div class="review-item"><div class="card-head"><div><b>${esc(d.customer_name)}</b><p class="tiny">${esc(d.name)}</p></div>${badge(d.status)}</div><p class="tiny">${esc(d.extraction.engine)} · ${when(d.created)}</p>${extractionView(d.extraction)}<a class="text-button" href="/api/documents/${d.id}/file">Inspect original ↓</a>${reviewControls('document',d)}</div>`).join(''):'<div class="empty">Upload a sample as Customer to create an evidence review.</div>'}</article><article class="card"><h3>Property estimates</h3>${r.properties.map(p=>`<div class="review-item"><div class="card-head"><b>${esc(p.customer_name)}</b>${badge(p.status)}</div><p class="tiny">${p.input.area} m² · ${esc(p.input.ward)}</p><h2 style="margin:8px 0">${money(p.result.value)}</h2><p class="tiny">${money(p.result.low)} – ${money(p.result.high)} · indicative 90% band</p><p class="notice">A review acknowledges the research estimate. It does not turn it into a legal appraisal or credit approval.</p><details><summary class="tiny">Model trace</summary><div class="evidence">${esc(p.result.model_version)}\n${esc(p.result.model_sha256)}</div></details>${reviewControls('property',p)}</div>`).join('')}</article></div>`;}
function reviewControls(kind,item){return item.status==='pending'?`<textarea id="note-${item.id}" maxlength="500" placeholder="Reviewer note (required to reject)"></textarea><div class="row">${button('Reject','review','danger',`data-kind="${kind}" data-id="${item.id}" data-decision="reject"`)}${button(kind==='document'?'Approve demo income':'Acknowledge estimate','review','primary',`data-kind="${kind}" data-id="${item.id}" data-decision="approve" ${kind==='document'&&!item.extraction.valid_for_demo_review?'disabled':''}`)}</div>`:`<p class="tiny" style="margin-top:10px">Reviewed by ${esc(item.reviewer)}${item.note?' · '+esc(item.note):''}</p>`;}
async function auditPage(){const entries=await api('/api/audit');return head('An inspectable decision trail.','Versions, actions and hashes — no raw passwords or document text in the audit log.')+`<article class="card"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity / trace</th></tr></thead><tbody>${entries.map(a=>`<tr><td>${when(a.at)}</td><td>${esc(a.actor)}</td><td><b>${esc(a.action.replaceAll('_',' '))}</b></td><td>${esc(a.entity)}<br><small>${esc(a.detail)}</small></td></tr>`).join('')}</tbody></table></div></article>`;}
async function signalsPage(){const status=await api('/api/status');S.status=status;return head('A transparent service picture.','Local workflows stay usable when the research server is unavailable.')+`<div class="grid three">${stat('AVM engine','Local CPU','Frozen LightGBM artifact + model hash','⌂')}${stat('Qwen connection',status.qwen.online?'Online':'Evidence mode',status.qwen.online?'Private cecs-server1 SSH endpoint':'No LLM answer is simulated','✦')}${stat('Customer data','Local SQLite','No bank integration or real bank records','◈')}</div><div class="grid section"><article class="card"><h3>Macro research pipeline</h3><p class="muted" style="margin:13px 0">The existing research console is preserved. It requires its separate pipeline API and approved research artifacts on the server.</p><a class="button" href="/research/" target="_blank" rel="noopener">Open existing research console ↗</a><p class="notice">This local release does not invent macro observations or silently adjust AVM prices. Research mappings and policy remain provisional.</p></article><article class="card"><h3>Online path</h3><div class="metric-pair"><span>Profile inputs</span><strong>Self-reported / synthetic</strong></div><div class="metric-pair"><span>Document extraction</span><strong>Local PDF / Vision OCR</strong></div><div class="metric-pair"><span>Verification</span><strong>Deterministic + human</strong></div><div class="metric-pair"><span>Chat</span><strong>Authorized evidence only</strong></div><div class="metric-pair"><span>Financial decisions</span><strong>No automatic approval</strong></div></article></div>`;}
function sourcesPage(){return head('Know where every number comes from.','Separate simulated customer facts from observed listing data and model estimates.')+`<div class="grid"><article class="card"><h3>Local evidence registry</h3><table><thead><tr><th>Source</th><th>Nature</th><th>Use</th></tr></thead><tbody><tr><td>Customer profiles</td><td>Synthetic / self-reported</td><td>Demo financial-health rules</td></tr><tr><td>Sample payslip</td><td>Fictional employer, visibly watermarked</td><td>Extraction and review workflow</td></tr><tr><td>LightGBM Phase1</td><td>Research model of asking prices</td><td>Indicative home estimate</td></tr><tr><td>Area statistics</td><td>Historical Phase1 listing aggregates</td><td>Exploration, not appraisal</td></tr><tr><td>OpenStreetMap</td><td>Public map tiles only</td><td>Basemap, not price data</td></tr><tr><td>Peer comparison</td><td>100 seeded synthetic scores</td><td>Illustrative percentile</td></tr></tbody></table></article><article class="card"><h3>Research sources & mappings</h3><p class="muted" style="margin:15px 0">Chuntran's source-list, corpus, gold-label and mapping views remain in the research console. They are not replaced by synthetic research or auto-signed in a reviewer's name.</p><a class="button" href="/research/" target="_blank" rel="noopener">Inspect research console ↗</a><p class="notice">A separate server API is needed for that console. This app's login is not production SSO for the legacy research services.</p><p class="tiny">Partner logo sourced from Vietcombank's official website; use authorized by the project owner. This demo is not a bank-issued application.</p></article></div>`;}
function mapPage(){return head('Explore the neighborhood, with context.','Historical asking-price statistics by street — clearly separate from your home valuation.')+`<article class="card"><div class="row" style="justify-content:space-between;margin-bottom:20px"><h3>Hanoi area intelligence</h3><input id="streetSearch" aria-label="Search street or district" placeholder="Search a street or district…" style="max-width:300px;margin:0"></div><div class="map-layout"><div><div id="map"></div><p class="tiny" style="margin-top:10px">OpenStreetMap basemap. Markers show approximate district centers, not precise street geometry or a property's location.</p></div><div><div id="streetDetail" class="notice">Hover over a street below to inspect its observed price distribution.</div><div id="streetList" class="street-list"></div></div></div><p class="source-label">${esc(S.market.source)}. ${esc(S.market.notice)}</p></article>`;}
function initMap(){if(window.L){S.map=L.map('map',{scrollWheelZoom:false}).setView([21.025,105.82],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).addTo(S.map);for(const way of S.market.ways||[]){const st=S.market.streets[way.street_index];L.polyline(way.coords,{color:'#087b46',weight:5}).addTo(S.map).bindTooltip(esc(st.name)+' · '+money(st.median)+'/m²').on('mouseover',()=>selectStreet(way.street_index)).on('click',()=>selectStreet(way.street_index));}if(S.market.ways?.length)$('#map').nextElementSibling.textContent='Highlighted roads: public OpenStreetMap geometry. Other pins: approximate district centers. Neither represents parcel boundaries.';}else $('#map').innerHTML='<div class="empty">Map library offline. Street statistics remain available in the list.</div>';filterStreets('');}
function filterStreets(q){const rows=S.market.streets.filter(x=>(x.name+' '+x.district).toLowerCase().includes(q.toLowerCase())).slice(0,80);$('#streetList').innerHTML=rows.map(x=>`<div class="street-row" tabindex="0" data-street="${S.market.streets.indexOf(x)}"><b>${esc(place(x.name))}</b><span>${esc(place(x.district))} · ${x.n} observations</span><strong style="float:right">${money(x.median)}/m²</strong></div>`).join('')||'<div class="empty">No streets match your search.</div>';if(S.map){S.markers.forEach(m=>m.remove());S.markers=rows.slice(0,12).map(x=>L.circleMarker(x.center,{radius:7,color:'#087b46',fillOpacity:.55}).addTo(S.map).bindTooltip(esc(place(x.name))+' · '+money(x.median)+'/m²').on('mouseover',()=>selectStreet(S.market.streets.indexOf(x))));}}
function selectStreet(i){const x=S.market.streets[i];if(!x)return;$('#streetDetail').innerHTML=`<span class="eyebrow">Observed asking-price statistics</span><h3>${esc(place(x.name))}</h3><div class="stat-number">${money(x.median)}/m²</div><p>Middle 50%: ${money(x.low)} – ${money(x.high)}/m²</p><small>${x.n} historical observations · ${esc(place(x.district))}<br>Pin basis: district center. Not a formal valuation.</small>`;}
async function render(version=navigationVersion){let content='';switch(S.view){case'overview':content=overview();break;case'property':content=propertyPage();break;case'health':content=healthPage();break;case'documents':content=await documentsPage();break;case'clients':content=clientPage();break;case'appointments':content=appointmentsPage();break;case'reviews':content=await reviewPage();break;case'audit':content=await auditPage();break;case'signals':content=await signalsPage();break;case'sources':content=sourcesPage();break;case'map':content=mapPage();break;}if(version!==navigationVersion||!S.user)return;$('#content').innerHTML=content;polishCopy();if(S.view==='property'){populateDistricts();polishOptions();}if(S.view==='map')initMap();}
// UI convenience only: the API independently enforces read-only Advisor access to evidence.
const renderContent=render;
render=async function(version){await renderContent(version);if(version!==navigationVersion||!S.user)return;if(S.user.role==='advisor'){
  $$('[data-action="documents"]').forEach(b=>b.textContent='Review customer evidence →');
  if(S.view==='documents'&&$('.upload-box'))$('.upload-box').innerHTML='<h3>Read-only customer evidence</h3><p class="muted">Only the Customer account can upload a document. Ask the customer to submit a synthetic sample, then follow its review status here.</p>';
}};
const mobileBrand=document.createElement('span');mobileBrand.className='mobile-brand';mobileBrand.textContent='VinFinx';$('header').insertBefore(mobileBrand,$('.header-right'));
function openChat(){if(!S.user||S.user.role==='authenticator')return;workspace.syncChat();if(!$('#messages').children.length)workspace.message(S.cid,'Ask about this customer’s score, inputs or property estimate. If Qwen is unavailable, I will show a labelled evidence-only explanation.');if(!$('#chatDialog').open)$('#chatDialog').show();$('#chatInput').focus();}
function appendMessage(text,user=false,meta=''){const div=document.createElement('div');div.className='bubble'+(user?' user':'');div.textContent=text;if(meta){const small=document.createElement('small');small.textContent=meta;div.appendChild(small);}$('#messages').appendChild(div);$('#messages').scrollTop=999999;}
function simulator(){let d=$('#simulationDialog');if(!d){d=document.createElement('dialog');d.id='simulationDialog';document.body.appendChild(d);}const s=S.summary,h=s.health;d.innerHTML=`<div class="dialog-head"><h2>A borrowing budget, not an offer.</h2><button class="icon" data-close="simulationDialog" aria-label="Close simulator">×</button></div><p class="notice">Assumptions: annual interest 10%, 20-year term, debt service capped at 40% of income, collateral cap 60% less existing principal. These are demo rules, not Vietcombank product terms.</p><div class="metric-pair"><span>Monthly income</span><strong>${money(s.profile.income)}</strong></div><div class="metric-pair"><span>Existing monthly debt payment</span><strong>${money(s.profile.debt_payment)}</strong></div><div class="metric-pair"><span>Additional monthly payment budget</span><strong>${money(Math.max(0,s.profile.income*.4-s.profile.debt_payment))}</strong></div><div class="metric-pair"><span>Illustrative additional principal</span><strong>${money(h.illustrative_borrowing_capacity)}</strong></div><p class="tiny" style="margin:15px 0">Subject to income evidence, property review and actual bank underwriting. A wide AVM interval does not establish collateral value.</p>${appointmentButton()}`;d.showModal();}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a,[data-customer]');if(!el)return;try{if(el.dataset.close){$('#'+el.dataset.close).close();return;}if(el.dataset.nav){await navigate(el.dataset.nav);return;}if(el.dataset.customer){await navigate(S.view,el.dataset.customer);return;}const a=el.dataset.action;if(!a)return;if(['property','documents'].includes(a)){if(!NAV[S.user.role].some(x=>x[0]===a)){toast('Customer documents are reviewed in the Authenticator workspace.');return;}await navigate(a);}if(a==='chat')openChat();if(a==='simulate')simulator();if(a==='appointment'){for(const d of $$('dialog[open]'))d.close();$('#appointmentDialog').dataset.customer=S.cid;$('#appointmentDialog').showModal();}if(a==='review'){const note=$('#note-'+el.dataset.id).value.trim();if(el.dataset.decision==='approve'&&!confirm('Approve this synthetic evidence / acknowledge this research estimate?'))return;el.disabled=true;const outcome=await workspace.run('Record human review','review',()=>api('/api/review',{kind:el.dataset.kind,id:el.dataset.id,action:el.dataset.decision,note}));if(outcome.stale)return;toast('Review recorded. Customer profile updates after refresh.');if(S.view==='reviews')await navigate('reviews');}}catch(err){toast(err.message);el.disabled=false;}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]'),submitButtons=[...form.querySelectorAll('[type=submit]')];
 const cid=S.cid,user=S.user,view=S.view;
 const current=()=>S.user===user&&S.cid===cid&&S.view===view;
 submitButtons.forEach(button=>button.disabled=true);
 try{
  if(form.id==='loginForm'){const r=await api('/api/login',{email:$('#email').value,password:$('#password').value});$('#loginError').textContent='';await signIn(r.user);}
  if(form.id==='valuationForm'){
   workspace.remember();const property=Object.fromEntries(new FormData(form));
   if(e.submitter?.dataset.preview!==undefined){
    const outcome=await workspace.run('Run live AVM preview','valuation',()=>api('/api/inference',{customer_id:cid,property}));
    if(outcome.stale)return;
    if(current()){$('#valuationResult').innerHTML=propertyCard({property:{input:property,result:outcome.result.result,status:'live preview'}});$('#factors').innerHTML=factorList(outcome.result.result);const trace=document.createElement('p');trace.className='tiny inference-trace';trace.textContent='Computed live · '+outcome.result.result.inference.elapsed_ms+' ms · '+outcome.result.result.inference.id;$('#valuationResult').appendChild(trace);polishCopy();}
    toast('Live inference completed. Preview only: no valuation or review was saved.');return;
   }
   const outcome=await workspace.run('Calculate property estimate','valuation',async()=>{await api('/api/valuation',{customer_id:cid,property});return api('/api/summary?customer='+cid);});
   if(outcome.stale)return;workspace.clearDraft('property',cid);
   if(current()) {S.summary=outcome.result;$('#valuationResult').innerHTML=propertyCard(S.summary);$('#factors').innerHTML=factorList(S.summary.property.result);polishCopy();}
   toast('Estimate saved and added to the review queue.');
  }
  if(form.id==='profileForm'){
   const outcome=await workspace.run('Save financial profile','profile',()=>api('/api/profile',Object.fromEntries(new FormData(form))));
   if(outcome.stale)return;workspace.clearDraft('health',cid);toast('Profile saved. Income changes require a new evidence review.');if(current()){$('#content').replaceChildren();await navigate('health');}
  }
  if(form.id==='uploadForm'){
   const file=$('#documentFile').files[0];if(!file)throw Error('Choose a file.');if(file.size>6*1024*1024)throw Error('The maximum file size is 6 MB.');
   const outcome=await workspace.run('Extract payslip evidence','upload',async()=>{
    const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Unable to read this file.'));reader.readAsDataURL(file);});
    return api('/api/upload',{name:file.name,content});
   });if(outcome.stale)return;workspace.clearDraft('documents',cid);toast(outcome.result.duplicate?'This document is already in your evidence trail.':'Extraction saved. An Authenticator must approve the evidence.');if(current()){$('#content').replaceChildren();await navigate('documents');}
  }
  if(form.id==='chatForm'){
   const text=$('#chatInput').value.trim();if(!text)throw Error('Enter a question first.');$('#chatInput').value='';workspace.clearDraft('chat',cid);workspace.message(cid,text,true);
   const outcome=await workspace.run('Explain customer evidence','chat',()=>api('/api/chat',{customer_id:cid,message:text}));
   if(outcome.stale)return;const r=outcome.result;workspace.message(cid,r.message,false,sentence(r.mode)+' · Sources: '+r.evidence_ids.join(', '));
  }
  if(form.id==='appointmentForm'){
   const outcome=await workspace.run('Save conversation request','appointment',()=>api('/api/appointment',{customer_id:$('#appointmentDialog').dataset.customer,at:$('#appointmentAt').value,note:$('#appointmentNote').value}));
   if(outcome.stale)return;$('#appointmentDialog').close();form.reset();toast('Conversation request saved locally.');if(current()&&S.view==='appointments')await navigate('appointments');
  }
 }catch(err){if(form.id==='loginForm')$('#loginError').textContent=err.message;else if(S.user===user)toast(err.message);}
 finally{submitButtons.forEach(button=>button.disabled=false);workspace.syncBusy();}
});
document.addEventListener('change',async e=>{if(e.target.id==='districtSelect')populateWards();if(e.target.id==='wardSelect')populateStreets();if(['districtSelect','wardSelect'].includes(e.target.id)){polishOptions();workspace.remember();}if(e.target.id==='customerPicker')await navigate(S.view,e.target.value);});
document.addEventListener('input',e=>{if(e.target.id==='streetSearch')filterStreets(e.target.value);});
document.addEventListener('mouseover',e=>{const row=e.target.closest('[data-street]');if(row)selectStreet(Number(row.dataset.street));});
document.addEventListener('click',e=>{const row=e.target.closest('[data-street]');if(row)selectStreet(Number(row.dataset.street));});
document.addEventListener('focusin',e=>{const row=e.target.closest('[data-street]');if(row)selectStreet(Number(row.dataset.street));});
$('#togglePassword').addEventListener('click',()=>{const show=$('#password').type==='password';$('#password').type=show?'text':'password';$('#togglePassword').textContent=show?'Hide':'Show';$('#togglePassword').setAttribute('aria-pressed',String(show));});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{});}finally{await signedOut();}});
$('#menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
api('/api/me').then(r=>{if(r.user)signIn(r.user).catch(e=>toast(e.message));}).catch(e=>{$('#loginError').textContent=e.message;});
